// PostgREST GET retorna um JSON array como corpo de um único item n8n.
// Pode chegar como array direto ($input.item.json = [...]) ou,
// em algumas versões do n8n, encapsulado em raw.data.
const raw = $input.item.json;
const data = Array.isArray(raw) ? raw
           : Array.isArray(raw?.data) ? raw.data
           : [];

if (data.length === 0) {
  console.log('[INFO] Nenhum post sem capa encontrado neste lote.');
  return [];
}

console.log(`[INFO] ${data.length} posts sem capa encontrados.`);

return data.map(post => ({ json: post }));

// cover_source_url foi persistida pelo workflow de Insights durante o sync.
// Usar diretamente, sem nova chamada à Graph API.
// Fallback para thumbnail_url / media_url para posts históricos (antes do patch)
// que não tenham cover_source_url mas possam ter as URLs brutas.

const post = $input.item.json;

const coverUrl = post.cover_source_url
              || post.thumbnail_url
              || post.media_url
              || null;

return {
  json: {
    post_id:   post.post_id,
    username:  post.username,
    media_type: post.media_type,
    cover_url: coverUrl,
    has_url:   Boolean(coverUrl)
  }
};

// Verificar se o download produziu dados binários válidos.
const binary = $binary?.data;
const post   = $json;

if (!binary || !binary.mimeType) {
  return {
    json: {
      post_id:  post.post_id,
      username: post.username,
      ok:       false,
      reason:   'sem_dados_binarios'
    }
  };
}

// Detectar extensão a partir do Content-Type retornado
const MIME_EXT = {
  'image/jpeg': 'jpg',
  'image/jpg':  'jpg',
  'image/png':  'png',
  'image/webp': 'webp',
  'image/gif':  'gif'
};
const mimeType = binary.mimeType.split(';')[0].trim().toLowerCase();
const ext      = MIME_EXT[mimeType] || 'jpg';
const fileSize = binary.fileSize || 0;

// Rejeitar arquivos muito grandes (> 5 MB = 5_242_880 bytes)
if (fileSize > 5242880) {
  return {
    json: {
      post_id:   post.post_id,
      username:  post.username,
      ok:        false,
      reason:    'arquivo_muito_grande',
      file_size: fileSize
    }
  };
}

return {
  json: {
    post_id:   post.post_id,
    username:  post.username,
    mime_type: mimeType,
    ext:       ext,
    file_size: fileSize,
    ok:        true
  },
  binary: { data: binary }
};

// Montar o caminho no bucket e a URL pública final.
// A extensão vem do mimeType detectado no download — sem hardcode.

const post        = $json;
const supabaseUrl = $('Config').item.json.supabaseUrl;
const bucket      = $('Config').item.json.bucket;
const ext         = post.ext || 'jpg';
const mimeType    = post.mime_type || 'image/jpeg';

const storagePath = `${post.username}/${post.post_id}.${ext}`;
const publicUrl   = `${supabaseUrl}/storage/v1/object/public/${bucket}/${storagePath}`;
const uploadUrl   = `${supabaseUrl}/storage/v1/object/${bucket}/${storagePath}`;

return {
  json: {
    post_id:      post.post_id,
    username:     post.username,
    mime_type:    mimeType,
    ext:          ext,
    storage_path: storagePath,
    public_url:   publicUrl,
    upload_url:   uploadUrl
  },
  binary: { data: $binary?.data }
};

const response = $json;
const prevJson = $('Montar Caminho Storage').item.json;

const httpStatus = response.statusCode || 0;
const ok = httpStatus === 200 || httpStatus === 201;

if (!ok) {
  console.log(`[ERRO] Upload falhou para post_id=${prevJson.post_id}: HTTP ${httpStatus}`);
  return {
    json: {
      post_id:     prevJson.post_id,
      username:    prevJson.username,
      ok:          false,
      http_status: httpStatus,
      error_body:  JSON.stringify(response.body || {}).substring(0, 500)
    }
  };
}

return {
  json: {
    post_id:     prevJson.post_id,
    username:    prevJson.username,
    public_url:  prevJson.public_url,
    ok:          true,
    http_status: httpStatus
  }
};

const response = $json;
const postId   = $('Verificar Upload').item.json.post_id;

const httpStatus  = response.statusCode || 0;
const body        = response.body;
const updatedRows = Array.isArray(body) ? body : (body ? [body] : []);
const patchOk     = httpStatus === 200 && updatedRows.length > 0;

if (!patchOk) {
  console.log(`[ERRO] PATCH falhou para post_id=${postId}: HTTP ${httpStatus}, rows=${updatedRows.length}`);
  return {
    json: {
      post_id:      postId,
      status:       'erro_patch',
      http_status:  httpStatus,
      rows_updated: updatedRows.length
    }
  };
}

return {
  json: {
    post_id:      postId,
    status:       'sucesso',
    cover_url:    updatedRows[0]?.cover_url || null,
    rows_updated: updatedRows.length
  }
};

const items = $input.all();

const counts = {
  total:         items.length,
  sucesso:       0,
  sem_url:       0,
  erro_download: 0,
  erro_upload:   0,
  erro_patch:    0,
  desconhecido:  0
};

const erros = [];

for (const item of items) {
  const s = item.json?.status;
  if      (s === 'sucesso')       counts.sucesso++;
  else if (s === 'sem_url')       counts.sem_url++;
  else if (s === 'erro_download') { counts.erro_download++; erros.push({ tipo: 'download', post_id: item.json?.post_id, reason: item.json?.reason }); }
  else if (s === 'erro_upload')   { counts.erro_upload++;   erros.push({ tipo: 'upload',   post_id: item.json?.post_id, http: item.json?.http_status }); }
  else if (s === 'erro_patch')    { counts.erro_patch++;    erros.push({ tipo: 'patch',    post_id: item.json?.post_id, http: item.json?.http_status }); }
  else counts.desconhecido++;
}

console.log('[RESUMO]', JSON.stringify({ counts, erros }, null, 2));

return {
  json: {
    executado_em: new Date().toISOString(),
    counts,
    erros
  }
};
